import{_ as i,o as a,c as t,a2 as n}from"./chunks/framework.CjPXnAcb.js";const g=JSON.parse('{"title":"Git 与 GitHub：给代码装一台时光机","description":"","frontmatter":{"title":"Git 与 GitHub：给代码装一台时光机"},"headers":[],"relativePath":"prereq/03-git-and-github.md","filePath":"prereq/03-git-and-github.md","lastUpdated":1789063242000}'),e={name:"prereq/03-git-and-github.md"};function l(p,s,r,o,h,d){return a(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="_03-·-git-与-github-给代码装一台时光机" tabindex="-1">03 · Git 与 GitHub：给代码装一台时光机 <a class="header-anchor" href="#_03-·-git-与-github-给代码装一台时光机" aria-label="Permalink to &quot;03 · Git 与 GitHub：给代码装一台时光机&quot;">​</a></h1><blockquote><p>一句话说清这课解决什么问题：学会用 Git 给项目拍「快照」，改坏了能随时回头；再用 GitHub 把快照同步到云端，让全世界能看到你的 Wiki。</p></blockquote><h2 id="它是什么-大白话-一个生活比喻" tabindex="-1">它是什么？（大白话 + 一个生活比喻） <a class="header-anchor" href="#它是什么-大白话-一个生活比喻" aria-label="Permalink to &quot;它是什么？（大白话 + 一个生活比喻）&quot;">​</a></h2><p><strong>Git</strong> 是一个<strong>版本控制</strong>工具——说人话，就是<strong>给文件夹拍快照的时光机</strong>。你每改完一版代码，就拍一张快照存档；哪天改崩了，随时翻回任何一张旧快照。再也不用靠「最终版」「最终版2」「真的最终版」这种文件名续命了。</p><p><strong>GitHub</strong> 是一个网站，作用是<strong>存快照的云端仓库</strong>，同时也是全球程序员交流的平台。你把本地的快照传上去，既算备份，也能分享给别人。</p><p>一句话分清：<strong>Git 是装在你电脑上的工具（相机），GitHub 是网上的存照平台（云端相册）</strong>。两者经常一起用，但完全不是一回事——就像相机和朋友圈的关系。</p><h2 id="为什么我们需要它-和你要做的-wiki-挂钩" tabindex="-1">为什么我们需要它？（和你要做的 Wiki 挂钩） <a class="header-anchor" href="#为什么我们需要它-和你要做的-wiki-挂钩" aria-label="Permalink to &quot;为什么我们需要它？（和你要做的 Wiki 挂钩）&quot;">​</a></h2><p>你的 Wiki 站点代码会越写越多，难免有「改着改着改崩了」的时刻——有了 Git，一条命令就能回到昨天的好状态。更关键的是发布：你的线上地址 <a href="https://jlshdsdk.github.io/my-wiki/" target="_blank" rel="noreferrer">https://jlshdsdk.github.io/my-wiki/</a> 用的就是 <strong>GitHub Pages</strong>（GitHub 提供的免费静态网站托管），它直接从你 GitHub 上的仓库读文件来生成网页。所以流程必然是：本地改 → Git 存快照 → 推上 GitHub → 网站自动更新。</p><p>这里的几个术语先用相册比喻打个底：</p><ul><li><strong>仓库</strong>（repository）：被 Git 管起来的文件夹，相册本子本身。</li><li><strong>暂存（add）</strong>：从一堆改动里<strong>选出这次要拍的照片</strong>——不是所有改动都想进这一页。</li><li><strong>提交（commit）</strong>：把选好的照片<strong>贴成一页，并在页边写注释</strong>——这页改了啥。每个 commit 都是一张快照。</li><li><strong>推送（push）</strong>：<strong>把相册同步上云</strong>，传到 GitHub。</li><li><strong>克隆（clone）</strong>：<strong>从云端复印整本相册</strong>到本地——通常是你在新电脑上拿到一个项目的第一步。</li></ul><p>另外还有 <strong>GitHub Actions</strong>（GitHub 的自动机器人，可以帮你每次推送后自动构建网站）和<strong>部署</strong>（把做好的网站放到能访问的地方）这两个词，后面建站课会见到，现在混个脸熟即可。</p><h2 id="动手试一试-核心命令" tabindex="-1">动手试一试（核心命令） <a class="header-anchor" href="#动手试一试-核心命令" aria-label="Permalink to &quot;动手试一试（核心命令）&quot;">​</a></h2><p>空口学不会，来真练一遍。打开 cmd：</p><div class="language-bat vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bat</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\Users\\王奕博\\Desktop</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 先走到桌面（站在正确的工作目录里）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">md</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test-repo</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 建一个练手文件夹</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">cd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> test-repo</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 走进它</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git init</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 在这个文件夹里「建相册」：初始化一个新仓库</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git status</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 看看现在有哪些改动还没进相册（此时应该是空的）</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">echo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hello </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> note.txt</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 建一个测试文件，内容是 hello</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git add note.txt</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 暂存：把 note.txt 选出来，作为这次要拍的照片</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git commit -m </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;第一次练习提交&quot;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 提交：把选好的照片贴成一页，-m 后面是这页的注释</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">git log</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">rem</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"> 翻相册：列出所有历史快照，能看到刚才那条注释</span></span></code></pre></div><p>走完这四步（init → add → commit → log），你就完成了一次标准的 Git 工作流。日常写 Wiki 就是这个循环的重复：改文件 → add → commit → push。</p><p>练完了删掉练手文件夹即可（<code>cd ..</code> 后 <code>rd /s test-repo</code>，<code>/s</code> 表示连里面的文件一起删）。</p><h2 id="常见报错与怎么读它" tabindex="-1">常见报错与怎么读它 <a class="header-anchor" href="#常见报错与怎么读它" aria-label="Permalink to &quot;常见报错与怎么读它&quot;">​</a></h2><p>真实案例：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>fatal: not a git repository</span></span></code></pre></div><p>怎么读？</p><ol><li><code>fatal</code>——「致命错误」，意思是这条命令没法继续，直接停了。</li><li><code>not a git repository</code>——直译「这里不是一个 git 仓库」。翻译成相册比喻：<strong>你还没建相册，就用了相册命令</strong>。比如你在一个普通文件夹里直接敲 <code>git add</code> 或 <code>git commit</code>，Git 一看：这文件夹我没管着，没法办。</li></ol><p>排查思路：</p><ul><li>先敲 <code>git status</code> 确认自己是不是站在仓库里。如果报同样的错，说明这个文件夹没被 Git 管理。</li><li>常见原因是<strong>走错了文件夹</strong>——仓库其实在子目录里，你人在外面。用 <code>dir</code> 看看有没有 <code>.git</code> 文件夹（它就是相册本子的实体，Git 靠它认仓库）。</li><li>真没建过，就 <code>git init</code> 先建相册。</li></ul><p>这个报错其实很友好：它不破坏任何东西，只是拒绝干活，照着提示补一步就好。</p><h2 id="自测两题" tabindex="-1">自测两题 <a class="header-anchor" href="#自测两题" aria-label="Permalink to &quot;自测两题&quot;">​</a></h2><p><strong>第 1 题</strong>：Git 和 GitHub 是一回事吗？各用一句话说明。</p><details class="details custom-block"><summary>看答案</summary><p>不是。Git 是装在电脑上的版本控制工具，负责给项目拍快照、回滚（相机）；GitHub 是存快照的云端网站，负责备份和分享（云端相册）。Git 离了 GitHub 也能用，GitHub 离了 Git 就没意义。</p></details><p><strong>第 2 题</strong>：add、commit、push 分别对应相册流程里的哪一步？为什么 commit 前要先 add？</p><details class="details custom-block"><summary>看答案</summary><p>add = 选出这次要拍的照片（暂存）；commit = 把照片贴成一页并写注释（提交快照）；push = 相册同步上云（推送到 GitHub）。commit 前先 add，是因为你可能同时改了五个文件，但只想让其中两个进这一页快照——add 就是那道「挑选」的闸门。</p></details><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p><a href="./04-markdown.html">04 · Markdown</a>——学会这座 Wiki 里每一页用的写作格式，学完你就能开始往站里写自己的笔记了。</p>`,31)])])}const c=i(e,[["render",l]]);export{g as __pageData,c as default};
